import { useEffect, useState } from 'react';
import { useSelector } from 'react-redux';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { getAccountTransactions } from '../services/api';
import logo from '../assets/argentBankLogo.png';

function TransactionList() {
    const { accountId } = useParams();
    const navigate = useNavigate();
    const [transactions, setTransactions] = useState([]);
    const [account, setAccount] = useState(null);
    const [expandedTransaction, setExpandedTransaction] = useState(null);
    const [loading, setLoading] = useState(true);
    const { token, user } = useSelector(state => state.auth);

    const handleLogout = () => {
        // Dispatch logout action
        navigate('/');
    };

    useEffect(() => {
        const fetchData = async () => {
            try {
                setLoading(true);

                // Simuler la récupération des données du compte
                const accountData = {
                    id: accountId,
                    type: "Checking",
                    number: "x3448",
                    balance: 48098.43
                };
                setAccount(accountData);

                // Appel API pour récupérer les transactions
                // const response = await getAccountTransactions(accountId, token);

                // Simuler des données de transaction pour la démo
                const mockTransactions = [
                    {
                        id: '1',
                        date: '2020-02-27',
                        description: 'Golden Sun Bakery',
                        amount: 8.00,
                        balance: 298.00,
                        transactionType: 'Electronic',
                        category: 'Food',
                        notes: 'Lorem ipsum'
                    },
                    {
                        id: '2',
                        date: '2020-02-27',
                        description: 'Golden Sun Bakery',
                        amount: 8.00,
                        balance: 298.00,
                        transactionType: 'Electronic',
                        category: 'Food',
                        notes: 'Lorem ipsum'
                    },
                    {
                        id: '3',
                        date: '2020-02-27',
                        description: 'Golden Sun Bakery',
                        amount: 8.00,
                        balance: 298.00,
                        transactionType: 'Electronic',
                        category: 'Food',
                        notes: 'Lorem ipsum'
                    },
                    {
                        id: '4',
                        date: '2020-02-27',
                        description: 'Golden Sun Bakery',
                        amount: 8.00,
                        balance: 298.00,
                        transactionType: 'Electronic',
                        category: 'Food',
                        notes: 'Lorem ipsum'
                    },
                    {
                        id: '5',
                        date: '2020-02-27',
                        description: 'Golden Sun Bakery',
                        amount: 8.00,
                        balance: 298.00,
                        transactionType: 'Electronic',
                        category: 'Food',
                        notes: 'Lorem ipsum'
                    }
                ];

                setTransactions(mockTransactions);
            } catch (error) {
                console.error('Failed to fetch data', error);
            } finally {
                setLoading(false);
            }
        };

        fetchData();
    }, [accountId, token]);

    const toggleTransaction = (transactionId) => {
        setExpandedTransaction(expandedTransaction === transactionId ? null : transactionId);
    };

    if (loading) return <div>Loading...</div>;
    if (!account) return <div>Account not found</div>;

    return (
        <div>
            <nav className="main-nav">
                <Link className="main-nav-logo" to="/">
                    <img
                        className="main-nav-logo-image"
                        src={logo}
                        alt="Argent Bank Logo"
                    />
                    <h1 className="sr-only">Argent Bank</h1>
                </Link>
                <div>
                    <Link className="main-nav-item" to="/profile">
                        <i className="fa fa-user-circle"></i>
                        {user?.firstName || 'Tony'}
                    </Link>
                    <Link className="main-nav-item" to="/" onClick={handleLogout}>
                        <i className="fa fa-sign-out"></i>
                        Sign Out
                    </Link>
                </div>
            </nav>

            <main className="main bg-dark">
                {/* En-tête du compte */}
                <div className="account-header-transaction">
                    <Link to="/profile" className="back-link">
                        <i className="fa fa-times"></i>
                    </Link>
                    <div className="account-info-header">
                        <h2>Argent Bank {account.type} ({account.number})</h2>
                        <p className="account-balance-large">${account.balance.toLocaleString('en-US', {minimumFractionDigits: 2})}</p>
                        <p className="balance-label">Available balance</p>
                    </div>
                </div>

                {/* Liste des transactions */}
                <div className="transaction-list">
                    {transactions.map((transaction, index) => (
                        <div key={transaction.id} className="transaction-item">
                            <div className="transaction-row" onClick={() => toggleTransaction(transaction.id)}>
                                <div className="transaction-date">
                                    {new Date(transaction.date).toLocaleDateString('en-GB')}
                                </div>
                                <div className="transaction-description">
                                    {transaction.description}
                                </div>
                                <div className="transaction-amount">
                                    ${transaction.amount.toFixed(2)}
                                </div>
                                <div className="transaction-balance">
                                    ${transaction.balance.toFixed(2)}
                                </div>
                                <div className="transaction-toggle">
                                    <i className={`fa ${expandedTransaction === transaction.id ? 'fa-chevron-up' : 'fa-chevron-down'}`}></i>
                                </div>
                            </div>

                            {expandedTransaction === transaction.id && (
                                <div className="transaction-details">
                                    <div className="transaction-detail-item">
                                        <span className="detail-label">Transaction type</span>
                                        <span className="detail-value">{transaction.transactionType}</span>
                                    </div>
                                    <div className="transaction-detail-item">
                                        <span className="detail-label">Category</span>
                                        <span className="detail-value">
                                            {transaction.category}
                                            <i className="fa fa-pencil edit-icon"></i>
                                        </span>
                                    </div>
                                    <div className="transaction-detail-item">
                                        <span className="detail-label">Note</span>
                                        <span className="detail-value">
                                            {transaction.notes}
                                            <i className="fa fa-pencil edit-icon"></i>
                                        </span>
                                    </div>
                                </div>
                            )}
                        </div>
                    ))}
                </div>
            </main>

            <footer className="footer">
                <p className="footer-text">Copyright 2020 Argent Bank</p>
            </footer>
        </div>
    );
}

export default TransactionList;
